            let $regionNumber;
            utils_component_subscribe($$self, selectedScreen, $$value => $$invalidate(3, $selectedScreen = $$value));
            utils_component_subscribe($$self, disabledButtons, $$value => $$invalidate(4, $disabledButtons = $$value));
            utils_component_subscribe($$self, carNumber, $$value => $$invalidate(14, $carNumber = $$value));
